use std::fs

fn prec(op: string) -> int {
    if op == "^" { return 3 }
    if op == "*" || op == "/" { return 2 }
    if op == "+" || op == "-" { return 1 }
    0
}

fn convert(line: string) -> string {
    let cs: Vec<char> = line.chars().collect()
    let n: int = cs.len() as int
    let mut out: Vec<string> = []
    let mut stack: Vec<string> = []
    let mut want = true
    let mut i: int = 0
    while i < n {
        let c = cs[i as usize]
        if c == ' ' || c == '\t' || c == '\r' {
            i += 1
        } else if c >= '0' && c <= '9' {
            if !want { return "error" }
            let mut num = ""
            while i < n && cs[i as usize] >= '0' && cs[i as usize] <= '9' {
                num = num + cs[i as usize].to_string()
                i += 1
            }
            out.push(num)
            want = false
        } else if c == '(' {
            if !want { return "error" }
            stack.push("(")
            i += 1
        } else if c == ')' {
            if want { return "error" }
            let mut found = false
            while stack.len() > 0 {
                let top = stack.pop().unwrap_or("")
                if top == "(" {
                    found = true
                    break
                }
                out.push(top)
            }
            if !found { return "error" }
            i += 1
        } else if c == '+' || c == '-' || c == '*' || c == '/' || c == '^' {
            if want { return "error" }
            let op = c.to_string()
            let p = prec(op)
            while stack.len() > 0 {
                let top = stack[stack.len() - 1]
                if top == "(" { break }
                let tp = prec(top)
                if tp > p || (tp == p && op != "^") {
                    out.push(stack.pop().unwrap_or(""))
                } else {
                    break
                }
            }
            stack.push(op)
            want = true
            i += 1
        } else {
            return "error"
        }
    }
    if want { return "error" }
    while stack.len() > 0 {
        let top = stack.pop().unwrap_or("")
        if top == "(" { return "error" }
        out.push(top)
    }
    out.join(" ")
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" { continue }
        println(convert(line))
    }
}

